#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Patch: নতুন app icon (car + excavator + gear লোগো) বসানো হচ্ছে -- আগের
"Gari Bazar" টেক্সটওয়ালা আইকনটা বদলে নতুন ছবিটা public/icon-192.png,
public/icon-512.png, public/icon-maskable-512.png হিসেবে লেখা হবে।
এই স্ক্রিপ্ট রিপো রুট থেকে চালাও: python3 patch_app_icon.py
"""
import os
import sys
import base64

REPO_ROOT = os.getcwd()
PUBLIC_DIR = os.path.join(REPO_ROOT, "public")

FILES_B64 = {
    "icon-192.png": "",
    "icon-512.png": "",
    "icon-maskable-512.png": "",
}

def main():
    if not os.path.isdir(PUBLIC_DIR):
        print("ERROR: public/ ফোল্ডার পাওয়া যায়নি -- রিপো রুট থেকে চালাচ্ছ তো?")
        sys.exit(1)

    for filename, b64 in FILES_B64.items():
        target = os.path.join(PUBLIC_DIR, filename)
        new_bytes = base64.b64decode(b64)

        if os.path.exists(target):
            with open(target, "rb") as f:
                existing_bytes = f.read()
            if existing_bytes == new_bytes:
                print(f"SKIP: {filename} ইতিমধ্যে আপডেট করা আছে")
                continue

        with open(target, "wb") as f:
            f.write(new_bytes)
        print(f"OK: public/{filename} আপডেট হয়েছে")

if __name__ == "__main__":
    main()
    print("\nসম্পন্ন! এখন:")
    print("  git add public/icon-192.png public/icon-512.png public/icon-maskable-512.png")
    print('  git commit -m "feat: update app icon"')
    print("  git push")
